324:   descargarArchivo() {
325:     // Contenido del archivo de texto
326:     const contenidoArchivo = this.inscritosData.map(objeto => `${objeto.snp}, ${objeto.num_doc_icfes}`).join('\n');
327: 
328:     // Crear un objeto Blob con el contenido del archivo
329:     const blob = new Blob([contenidoArchivo], { type: 'text/plain' });
330: 
331:     // Crear un objeto URL del Blob
332:     const url = window.URL.createObjectURL(blob);
333: 
334:     // Crear un elemento <a> para descargar el archivo
335:     const a = document.createElement('a');
336:     a.href = url;
337:     a.download = 'archivo.txt'; // Nombre del archivo
338:     document.body.appendChild(a);
339: 
340:     // Simular un clic en el elemento <a> para iniciar la descarga
341:     a.click();
342: 
343:     // Limpiar el objeto URL y eliminar el elemento <a>
344:     window.URL.revokeObjectURL(url);
345:     document.body.removeChild(a);
346:   }
