54: export function getCookie(name: string): string | undefined {
55:   const value = '; ' + document.cookie;
56:   const parts = value.split('; ' + name + '=');
57:   if (parts.length == 2) {
58:     return parts.pop()?.split(';').shift();
59:   }
60:   return undefined;
61: }

